-- Empty databases only. Existing Meeter schemas are baselined at version 1.
create table app_users (id bigint not null auto_increment, created_at datetime(6) not null, password_hash varchar(100) not null, username varchar(64) not null, uuid uuid not null, human_id bigint not null, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table auth_tokens (id bigint not null auto_increment, expires_at datetime(6) not null, token_hash varchar(64) not null, owner_id bigint not null, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table cliques (id bigint not null auto_increment, clique_name varchar(32) not null, created_by_id bigint, capital_id bigint, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table events (me_coming_date datetime(6), me_leaving_date datetime(6), photo_file varchar(255), photo_name varchar(255), place_string varchar(200), id bigint not null, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table flatmates (id bigint not null, human_id bigint not null, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table interaction_human (id bigint not null auto_increment, created_at datetime(6) not null, created_by_id bigint not null, human_id bigint not null, interaction_id bigint not null, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table interactions (id bigint not null auto_increment, created_at datetime(6) not null, end_date datetime(6), long_desc varchar(10240), name varchar(128) not null, start_date datetime(6) not null, uuid uuid not null, created_by_id bigint, place_id bigint, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table meetings (place_string varchar(200), id bigint not null, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table people (id bigint not null auto_increment, birthday_date date, demo boolean default false not null, fb_link varchar(2048), gender varchar(1), lives_in varchar(200), name varchar(100) not null, profile_photo_file varchar(100), surname varchar(100), uuid uuid not null, created_by_id bigint, clique_id bigint, home_id bigint, profile_photo_id bigint, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table photos (id bigint not null auto_increment, generation_time datetime(6), latitude float(53), longitude float(53), photo_name varchar(255), photo_type enum ('EVENT','PROFILE_PICTURE','SUPERPOWER','TRIP') not null, uuid uuid, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table places (id bigint not null auto_increment, category varchar(100), latitude float(53) not null, longitude float(53) not null, name varchar(200) not null, created_by_id bigint, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table quote_game_candidates (id bigint not null auto_increment, created_at datetime(6) not null, created_by_id bigint not null, game_id bigint not null, human_id bigint not null, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table quote_game_cliques (id bigint not null auto_increment, created_at datetime(6) not null, created_by_id bigint not null, clique_id bigint not null, game_id bigint not null, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table quote_game_rounds (id bigint not null auto_increment, created_at datetime(6) not null, deadline_at datetime(6), position integer not null, quote_text varchar(10240) not null, started_at datetime(6), created_by_id bigint not null, correct_author_id bigint not null, game_id bigint not null, quote_id bigint not null, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table quote_games (id bigint not null auto_increment, created_at datetime(6) not null, finished_at datetime(6), scope_label varchar(512) not null, scope_type varchar(10) not null, seconds_per_question integer not null, uuid uuid not null, created_by_id bigint not null, player_human_id bigint not null, visit_id bigint, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table quote_guesses (id bigint not null auto_increment, created_at datetime(6) not null, correct bit not null, elapsed_millis bigint not null, self_quote bit not null, timed_out bit not null, created_by_id bigint not null, guessed_author_id bigint, round_id bigint not null, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table quotes (id bigint not null auto_increment, add_time datetime(6) not null, is_public bit not null, quote_text varchar(10240) not null, uuid uuid not null, created_by_id bigint not null, author_id bigint, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table trip_place (id bigint not null auto_increment, created_at datetime(6) not null, created_by_id bigint not null, place_id bigint not null, trip_id bigint not null, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table trips (id bigint not null, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table user_roles (user_id bigint not null, role enum ('ROLE_ADMIN','ROLE_USER') not null) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table visits (duration integer not null, id bigint not null, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
create table weddings (had_after bit not null, was_i_invited boolean default false not null, id bigint not null, bride_id bigint not null, ceremony_place_id bigint, groom_id bigint not null, hotel_id bigint, party_place_id bigint, primary key (id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_unicode_ci;
